"use client";

import { AnimatePresence, LayoutGroup } from "motion/react";
import { useId, useRef, useState } from "react";


import { useTimers } from "../auth/shared/use-timers";
import { BlockFrame } from "../parts/block-frame";
import { SearchField } from "./shared/search-field";
import type { Chip } from "./shared/email-chip";
import { PendingRow } from "./shared/pending-row";
import type { Role } from "./shared/role-menu";
import { nameFromEmail } from "./shared/roster";
import { ME, type Member, type PendingInvite, SEATS, START_MEMBERS, START_PENDING } from "./team-members/data";
import { InviteField } from "./team-members/invite-field";
import { MemberRow } from "./team-members/member-row";
import { SeatMeter } from "./team-members/seat-meter";

const VALID = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/**
 * The clinic's members: seats used, an invite field that turns addresses into
 * chips, a searchable list with role menus, and pending invites. Sent chips
 * fly into the pending list. Escape cancels a removal that is still waiting.
 */
export function TeamMembers({ className }: { className?: string }) {
  const titleId = useId();
  const { later } = useTimers();
  const removal = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [members, setMembers] = useState<Member[]>(START_MEMBERS);
  const [pending, setPending] = useState<PendingInvite[]>(START_PENDING);
  const [chips, setChips] = useState<Chip[]>([]);
  const [draft, setDraft] = useState("");
  const [role, setRole] = useState<Role>("Practitioner");
  const [note, setNote] = useState<string | null>(null);
  const [shake, setShake] = useState(0);
  const [query, setQuery] = useState("");
  const [removing, setRemoving] = useState<string | null>(null);
  const [status, setStatus] = useState("");

  const taken = (email: string) =>
    members.some((member) => member.person.email === email) || pending.some((invite) => invite.email === email);

  const toChips = (text: string, current: Chip[]) => {
    const added: Chip[] = [];
    for (const raw of text.split(/[,;\s]+/)) {
      const email = raw.trim().toLowerCase();
      if (!email || current.some((chip) => chip.email === email) || added.some((chip) => chip.email === email)) continue;
      if (taken(email)) {
        setNote(`${email} is already on the team or invited.`);
        continue;
      }
      added.push({ email, name: nameFromEmail(email), hue: ((current.length + added.length) % 5) + 1, valid: VALID.test(email) });
    }
    return [...current, ...added];
  };

  const commit = (text: string) => {
    setNote(null);
    setChips(toChips(text, chips));
    setDraft("");
  };

  const send = () => {
    const all = draft.trim() ? toChips(draft, chips) : chips;
    setDraft("");
    const good = all.filter((chip) => chip.valid);
    const bad = all.filter((chip) => !chip.valid);
    const free = SEATS - members.length - pending.length;
    if (good.length > free) {
      setChips(all);
      setShake((value) => value + 1);
      setNote(`Only ${free} ${free === 1 ? "seat is" : "seats are"} free. Remove ${good.length - free} or add seats to the plan.`);
      return;
    }
    setPending((current) => [...good.map((chip) => ({ email: chip.email, name: chip.name, hue: chip.hue, role, sent: "Sent just now" })), ...current]);
    setChips(bad);
    if (bad.length) {
      setShake((value) => value + 1);
      setNote("Fix or remove the addresses marked in red.");
    } else {
      setNote(null);
    }
    if (good.length) setStatus(`${good.length} ${good.length === 1 ? "invite" : "invites"} sent as ${role}.`);
  };

  const startRemoval = (id: string) => {
    if (removal.current) clearTimeout(removal.current);
    setRemoving(id);
    removal.current = later(() => {
      setMembers((current) => current.filter((member) => member.person.id !== id));
      setRemoving(null);
      removal.current = null;
    }, 4000);
  };

  const undo = () => {
    if (removal.current) clearTimeout(removal.current);
    removal.current = null;
    setRemoving(null);
    setStatus("Removal cancelled.");
  };

  const needle = query.trim().toLowerCase();
  const shown = members.filter((member) => !needle || `${member.person.name} ${member.person.email}`.toLowerCase().includes(needle));

  return (
    <BlockFrame
      aria-labelledby={titleId}
      className={className}
      onKeyDown={(event) => {
        if (event.key === "Escape" && removing) undo();
      }}
    >
      <LayoutGroup>
        <header className="flex flex-col gap-4 border-b border-border px-5 py-4 @lg:flex-row @lg:items-start @lg:justify-between">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Members
            </h2>
            <p className="text-sm text-muted-foreground">Manage who works in the Harbour Street workspace.</p>
          </div>
          <SeatMeter members={members.length} pending={pending.length} total={SEATS} />
        </header>

        <div className="border-b border-border px-5 py-4">
          <InviteField
            chips={chips}
            draft={draft}
            role={role}
            shake={shake}
            note={note}
            onDraft={setDraft}
            onCommit={commit}
            onRemove={(email) => setChips((current) => current.filter((chip) => chip.email !== email))}
            onRole={setRole}
            onSend={send}
          />
        </div>

        <section aria-labelledby={`${titleId}-list`} className="py-3">
          <div className="flex flex-wrap items-center justify-between gap-3 px-5 pb-2">
            <h3 id={`${titleId}-list`} className="text-sm font-medium">
              Team <span className="text-muted-foreground">{members.length}</span>
            </h3>
            <label className="w-full @md:w-64">
              <span className="sr-only">Search members</span>
              <SearchField placeholder="Search by name or email" value={query} onChange={(event) => setQuery(event.target.value)} />
            </label>
          </div>
          <ul className="flex flex-col">
            <AnimatePresence initial={false}>
              {shown.map((member) => (
                <MemberRow
                  key={member.person.id}
                  member={member}
                  isMe={member.person.id === ME}
                  removing={removing === member.person.id}
                  onRole={(next) => setMembers((current) => current.map((item) => (item.person.id === member.person.id ? { ...item, role: next } : item)))}
                  onRemove={() => startRemoval(member.person.id)}
                  onUndo={undo}
                />
              ))}
            </AnimatePresence>
          </ul>
          {shown.length === 0 ? <p className="px-5 py-4 text-sm text-muted-foreground">Nobody matches “{query.trim()}”.</p> : null}
        </section>

        <section aria-labelledby={`${titleId}-pending`} className="border-t border-border py-3">
          <h3 id={`${titleId}-pending`} className="px-5 pb-1 text-sm font-medium">
            Pending invites <span className="text-muted-foreground">{pending.length}</span>
          </h3>
          <ul className="flex flex-col">
            <AnimatePresence initial={false}>
              {pending.map((invite) => (
                <PendingRow
                  key={invite.email}
                  invite={invite}
                  layoutId={`invite-${invite.email}`}
                  onResend={() => {
                    setPending((current) => current.map((item) => (item.email === invite.email ? { ...item, sent: "Sent again just now" } : item)));
                    setStatus(`Invite sent again to ${invite.email}.`);
                  }}
                  onRevoke={() => {
                    setPending((current) => current.filter((item) => item.email !== invite.email));
                    setStatus(`Invite to ${invite.email} revoked.`);
                  }}
                />
              ))}
            </AnimatePresence>
          </ul>
          {pending.length === 0 ? <p className="px-5 py-2 text-sm text-muted-foreground">No invites waiting.</p> : null}
        </section>
        <p aria-live="polite" className="sr-only">
          {status}
        </p>
      </LayoutGroup>
    </BlockFrame>
  );
}

