"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { XIcon } from "../../parts/icons";
import { PersonAvatar } from "./person-avatar";

/** One address waiting in the invite field. */
export interface Chip {
  email: string;
  name: string;
  hue: number;
  valid: boolean;
}

/** Props for one chip. `shake` changes on each refused send, so a wrong chip shakes again. */
export interface EmailChipProps {
  chip: Chip;
  /** Shared with the row the chip turns into, so it flies there. */
  layoutId: string;
  shake: number;
  onRemove: () => void;
}

/** An address as a removable chip: the avatar and address, red when the address is not valid. */
export function EmailChip({ chip, layoutId, shake, onRemove }: EmailChipProps) {
  const reduce = useReducedMotion();
  const shaking = !chip.valid && shake > 0 && !reduce;

  return (
    <motion.span layoutId={layoutId} layout="position" className="inline-flex">
      <motion.span
        key={shaking ? shake : 0}
        initial={false}
        animate={shaking ? { x: [0, -5, 5, -4, 4, 0] } : { x: 0 }}
        transition={{ duration: 0.36 }}
        className={cn(
          "inline-flex max-w-full items-center gap-1.5 rounded-full border py-0.5 pr-0.5 pl-0.5 text-sm",
          chip.valid ? "border-border" : "border-destructive text-destructive",
        )}
      >
        <PersonAvatar name={chip.name} hue={chip.hue} size="sm" className="scale-75" />
        <span className="max-w-48 truncate">{chip.email}</span>
        {chip.valid ? null : <span className="sr-only">, not a valid address</span>}
        <Button type="button" variant="ghost" size="icon" className="size-6" aria-label={`Remove ${chip.email}`} onClick={onRemove}>
          <XIcon aria-hidden="true" className="size-3" />
        </Button>
      </motion.span>
    </motion.span>
  );
}

import { cn } from "@/lib/utils";

import { initials, type Presence } from "./roster";

const FILLS = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"];
const DOTS = { online: "bg-success", away: "bg-warning", offline: "bg-muted-foreground" } satisfies Record<Presence, string>;
const SIZES = { sm: "size-7 text-xs", md: "size-9 text-sm", lg: "size-20 text-2xl" };

/** Props for a person's avatar. The name sits beside it, so the avatar itself is hidden from screen readers. */
export interface PersonAvatarProps {
  name: string;
  hue: number;
  size?: keyof typeof SIZES;
  presence?: Presence;
  /** Draws a ring in the card colour, for avatars that overlap in a stack. */
  ring?: boolean;
  className?: string;
}

/** A round avatar: the person's initials on one of the five chart hues, with an optional presence dot. */
export function PersonAvatar({ name, hue, size = "md", presence, ring, className }: PersonAvatarProps) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex shrink-0", className)}>
      <span
        className={cn(
          "flex items-center justify-center rounded-full font-semibold text-primary-foreground select-none",
          FILLS[(hue - 1) % 5],
          SIZES[size],
          ring && "ring-2 ring-card",
        )}
      >
        {initials(name)}
      </span>
      {presence ? <span className={cn("absolute right-0 bottom-0 size-2.5 rounded-full ring-2 ring-card", DOTS[presence])} /> : null}
    </span>
  );
}

/** Which part of the clinic a person works in. */
export type Team = "Practitioners" | "Front desk" | "Operations";

/** Whether a person is around right now. */
export type Presence = "online" | "away" | "offline";

/** One person at Fernhill's Harbour Street clinic. Every name is invented. */
export interface Person {
  id: string;
  name: string;
  email: string;
  title: string;
  team: Team;
  /** Which of the five chart hues fills their avatar, 1 to 5. */
  hue: 1 | 2 | 3 | 4 | 5;
  presence: Presence;
  /** When they were last active, in words. */
  lastActive: string;
  place: string;
  bio: string;
  /** What they are working on this week. */
  focus: string;
}

const person = (
  id: string,
  name: string,
  title: string,
  team: Team,
  hue: Person["hue"],
  presence: Presence,
  lastActive: string,
  place: string,
  bio: string,
  focus: string,
): Person => ({
  id,
  name,
  email: `${name.toLowerCase().replace(/[^a-z]+/g, ".")}@harbourstreet.clinic`,
  title,
  team,
  hue,
  presence,
  lastActive,
  place,
  bio,
  focus,
});

