  person("mei", "Mei Tanaka", "Sports therapist", "Practitioners", 5, "offline", "Active yesterday", "Room 3, ground floor", "Former county swimmer. Treats shoulders, mostly overhead athletes.", "Shoulder screening for the swim club"),
