  person("elif", "Elif Demir", "Billing lead", "Operations", 4, "offline", "Active 2 days ago", "Office, first floor", "Chases insurers so the practitioners do not have to.", "Closing October invoices"),
  person("hannah", "Hannah Moore", "Podiatrist", "Practitioners", 5, "online", "Active now", "Room 6, first floor", "Feet, gait and orthotics. Brings a treadmill to every argument.", "Gait lab booking slots"),
