import { UserPlusIcon } from "../icons";
import { type Chip, EmailChip } from "../shared/email-chip";
import { type Role, RoleMenu } from "../shared/role-menu";

/** Props for the invite field. The parent owns the chips so it can fly them into the pending list. */
export interface InviteFieldProps {
  chips: Chip[];
  draft: string;
  role: Role;
  shake: number;
  note: string | null;
  onDraft: (value: string) => void;
  /** Turns the typed text into chips. */
  onCommit: (text: string) => void;
  onRemove: (email: string) => void;
  onRole: (role: Role) => void;
  onSend: () => void;
}

const COMMIT_KEYS = new Set(["Enter", ",", ";", " "]);

/**
 * Where addresses are typed. Enter, comma, semicolon or Space turns the text
 * into a chip; Backspace on an empty field removes the last chip.
 */
export function InviteField({ chips, draft, role, shake, note, onDraft, onCommit, onRemove, onRole, onSend }: InviteFieldProps) {
  const id = useId();

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (COMMIT_KEYS.has(event.key)) {
      if (!draft.trim()) {
        if (event.key === "Enter" && chips.length) {
          event.preventDefault();
          onSend();
        }
        return;
      }
      event.preventDefault();
      onCommit(draft);
    } else if (event.key === "Backspace" && !draft && chips.length) {
      event.preventDefault();
      onRemove(chips[chips.length - 1]!.email);
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <label htmlFor={id} className="text-sm font-medium">
        Invite people
      </label>
      <div className="flex flex-col gap-2 @lg:flex-row @lg:items-start">
        <Input
          id={id}
          type="text"
          inputMode="email"
          autoComplete="off"
          value={draft}
          placeholder="name@harbourstreet.clinic"
          onChange={(event) => onDraft(event.target.value)}
          onKeyDown={onKeyDown}
          onBlur={() => draft.trim() && onCommit(draft)}
          onPaste={(event) => {
            const text = event.clipboardData.getData("text");
            if (/[,;\s]/.test(text.trim())) {
              event.preventDefault();
              onCommit(draft + text);
            }
          }}
          aria-describedby={`${id}-note`}
          className="min-w-0 flex-1"
        />
        <div className="flex items-center gap-2">
          <RoleMenu label="Role for new invites" value={role} onChange={onRole} />
          <Button type="button" onClick={onSend} disabled={!chips.length && !draft.trim()}>
            <UserPlusIcon aria-hidden="true" className="size-4" />
            Send invites
          </Button>
        </div>
      </div>
      {chips.length ? (
        <ul aria-label="Addresses to invite" className="flex flex-wrap gap-1.5">
          {chips.map((chip) => (
            <li key={chip.email}>
              <EmailChip chip={chip} layoutId={`invite-${chip.email}`} shake={shake} onRemove={() => onRemove(chip.email)} />
            </li>
          ))}
        </ul>
      ) : null}
      <p id={`${id}-note`} aria-live="polite" className={cn("text-sm", note ? "text-destructive" : "text-muted-foreground")}>
        {note ?? "Separate addresses with a comma or press Enter. Invites expire after 7 days."}
      </p>
    </div>
  );
}

