/** Seats used out of the plan's total, with a bar split into members and pending invites. */
export function SeatMeter({ members, pending, total, className }: SeatMeterProps) {
  const used = members + pending;
  // SAFETY: the style holds only the `--fill` custom property, which React passes through untouched.
  const memberFill = { "--fill": `${(members / total) * 100}%` } as CSSProperties;
  // SAFETY: the style holds only the `--fill` custom property, which React passes through untouched.
  const pendingFill = { "--fill": `${(pending / total) * 100}%` } as CSSProperties;
  return (
    <div className={cn("flex w-full flex-col gap-1.5 @lg:w-56", className)}>
      <p className="flex items-baseline justify-between gap-2 text-sm">
        <span className="text-muted-foreground">Seats</span>
        <span aria-live="polite">
          <RollingText text={String(used)} className="font-semibold" /> of {total} used
        </span>
      </p>
      <div
        role="meter"
        aria-label="Seats used"
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={used}
        aria-valuetext={`${used} of ${total} seats used, ${pending} by pending invites`}
        className="flex h-2 gap-0.5 overflow-hidden rounded-full bg-muted"
      >
        <span className="w-(--fill) bg-chart-1 motion-safe:transition-all motion-safe:duration-500" style={memberFill} />
        <span className="w-(--fill) bg-chart-4 motion-safe:transition-all motion-safe:duration-500" style={pendingFill} />
      </div>
      <p className="flex gap-3 text-xs text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <span aria-hidden="true" className="size-2 rounded-full bg-chart-1" />
          {members} members
        </span>
        <span className="flex items-center gap-1.5">
          <span aria-hidden="true" className="size-2 rounded-full bg-chart-4" />
          {pending} pending
        </span>
      </p>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}
